import{_ as s,o as a,c as r,a0 as t}from"./chunks/framework.Caz7a20Z.js";const c=JSON.parse('{"title":"生物量初稿出炉！还开垦了 DeepSeek Harness 新工具","description":"生物量那篇论文初稿写完了，虽然基本靠 AI 但思路是自己的；金枪鱼那篇分析基本完成明天开写；另外试了 DeepSeek Harness 跑另一篇论文的数据分析，省钱还不受 Codex 限额制约。","frontmatter":{"title":"生物量初稿出炉！还开垦了 DeepSeek Harness 新工具","date":"2026-09-03T00:00:00.000Z","tags":["日记"],"description":"生物量那篇论文初稿写完了，虽然基本靠 AI 但思路是自己的；金枪鱼那篇分析基本完成明天开写；另外试了 DeepSeek Harness 跑另一篇论文的数据分析，省钱还不受 Codex 限额制约。"},"headers":[],"relativePath":"posts/diary-20260903.md","filePath":"posts/diary-20260903.md","lastUpdated":null}'),o={name:"posts/diary-20260903.md"};function n(p,e,d,i,l,g){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="生物量初稿出炉-还开垦了-deepseek-harness-新工具" tabindex="-1">生物量初稿出炉！还开垦了 DeepSeek Harness 新工具 <a class="header-anchor" href="#生物量初稿出炉-还开垦了-deepseek-harness-新工具" aria-label="Permalink to &quot;生物量初稿出炉！还开垦了 DeepSeek Harness 新工具&quot;">​</a></h1><p>昨天漏了一篇（懒得补了哈哈，欠着就欠着吧），今天进度倒是不少，一次性攒了个大的 📦。</p><h2 id="生物量那篇-初稿写完了-✍️" tabindex="-1">生物量那篇：初稿写完了 ✍️ <a class="header-anchor" href="#生物量那篇-初稿写完了-✍️" aria-label="Permalink to &quot;生物量那篇：初稿写完了 ✍️&quot;">​</a></h2><p>先说最重的：<strong>生物量那篇论文的初稿，今天撰写完成</strong> ✅！</p><p>说句实话，这一稿<strong>基本是靠着 AI 写出来的</strong>，但<strong>思路是我的</strong>——问题怎么提、故事怎么讲、结论往哪儿落，这些得我自己先想明白，AI 才能照着往下写。就像一个手脚特别快的助手，你把骨架搭好，它帮你把肉填上去。</p><p><strong>写得还是很粗糙</strong>，这点我心里有数。有些段落读着还是&quot;AI 味&quot;重，逻辑衔接也还有硬拐弯的地方。但没关系，<strong>准备先写完</strong>——先把完整的稿子立起来，拿着主要结论去<strong>跟老师汇报</strong>，等老师把方向性的意见给回来，再集中改一轮。</p><p>先有再好，比憋着憋着什么都不出，强太多了。</p><h2 id="金枪鱼那篇-分析基本完成-明天开写" tabindex="-1">金枪鱼那篇：分析基本完成，明天开写 <a class="header-anchor" href="#金枪鱼那篇-分析基本完成-明天开写" aria-label="Permalink to &quot;金枪鱼那篇：分析基本完成，明天开写&quot;">​</a></h2><p>第二条线也有进展：<strong>金枪鱼那篇的分析基本完成了</strong> 🐟。</p><p>不过说&quot;基本&quot;，是因为<strong>还有一小部分没分析完</strong>——就差那么一截。但主体结果已经出来了，够支撑起文章的主干，所以<strong>明天可以开始写了</strong>。</p><p>边写边等剩下那点分析跑完，节奏上刚好衔接。粗糙点不怕，先把全文推出来。</p><h2 id="新玩具-deepseek-harness" tabindex="-1">新玩具：DeepSeek Harness <a class="header-anchor" href="#新玩具-deepseek-harness" aria-label="Permalink to &quot;新玩具：DeepSeek Harness&quot;">​</a></h2><p>今天还干了件挺有意思的事——<strong>试了 DeepSeek Harness，用它开启我的另一篇论文</strong> 🤖。</p><p>具体玩法是：我<strong>把整理好的数据喂给它</strong>，让它<strong>先帮我做一轮分析</strong>。数据我都已经整理好了，初步思路也已经有了，交给它去跑，正好省下我盯代码、调 bug 的时间。</p><p>用下来最大的感受有两个：</p><p>一是<strong>不得不说还挺省钱的</strong> 💰。不心疼额度，就能放开手脚让它多试几轮、多换几种思路，分析反而更透。</p><p>二是——<strong>主要是我不想让 Codex 的限额制约了我的科研</strong> 😤。那个 5 小时一掐的限额，最难受的不是少干了多少活，而是你正顺手、灵感正旺的时候突然被打断，节奏全散了。科研这事儿最怕断片，多备一条路，就不至于被一个工具卡住脖子。</p><h2 id="就这样-明天继续" tabindex="-1">就这样，明天继续 <a class="header-anchor" href="#就这样-明天继续" aria-label="Permalink to &quot;就这样，明天继续&quot;">​</a></h2><p>今天三条线同时推：生物量初稿落地、金枪鱼分析收尾、新论文借 Harness 起步。虽然稿子都还粗，但都在往前走，这就够了。</p><p>明天金枪鱼开写，顺便看看 Harness 那边分析得怎么样。加油 💪！</p>',20)])])}const u=s(o,[["render",n]]);export{c as __pageData,u as default};
